namespace selection {

enum class AlgorithmType { RDP, SED };

std::vector<std::size_t> simplify_trajectory(const core::TrajectoryView &, AlgorithmType,
                                             std::size_t);

// Simplifies every trajectory, trajectory i keeping budgets[i] points
core::Simplification simplify_database(const core::TrajectoryDb &trajectories,
                                       AlgorithmType algorithm,
                                       std::span<const std::size_t> budgets);

} // namespace selection
#pragma once

#include "backend/engine/core/trajectory_db.hpp"

#include <cstddef>
#include <cstdint>
#include <vector>

namespace query {

struct KnnQuery {
    std::size_t query_index;            // index into KnnWorkload::queries
    std::vector<std::size_t> reference; // knn in the uncompressed database, closest first
};

struct KnnConfig {
    std::size_t k = 5;
    std::size_t query_count = 10; // 0 = use every trajectory in the query pool
    double p = 0.5; // top-k tau penalty for a pair one list holds neither of, in [0, 1]
};

struct KnnWorkload {
    core::TrajectoryDb queries;
    std::vector<KnnQuery> entries;
    std::size_t k;
    double p = 0.5;
};

// Samples query_count trajectories from query_pool (the held-out split) and stores their k
// nearest neighbours in original as the reference answer.
KnnWorkload generate_knn_queries(const core::TrajectoryDb &original,
                                 const core::TrajectoryDb &query_pool, const KnnConfig &config = {},
                                 std::uint64_t seed = 42);

// Indices into trajectories of the k trajectories closest to query by discrete Fréchet
// distance, closest first. Equal distances are ordered by database index.
std::vector<std::size_t> knn(const core::TrajectoryDb &trajectories,
                             const core::TrajectoryView &query, std::size_t k);

} // namespace query
#pragma once

#include "backend/engine/core/trajectory_db.hpp"

#include <cassert>
#include <cstddef>
#include <cstdint>
#include <span>
#include <vector>

// example
// core::Simplification s;
// m_offsets = [0]              m_kept = []

// s.add_trajectory({0, 4, 9});
//  m_offsets = [0, 3]           m_kept = [0, 4, 9]

// s.add_trajectory({0, 4});
//  m_offsets = [0, 3, 5]        m_kept = [0, 4, 9, 0, 4]

// s.add_trajectory({0, 2, 5, 7});
//  m_offsets = [0, 3, 5, 9]     m_kept = [0, 4, 9, 0, 4, 0, 2, 5, 7]

namespace core {

class Simplification {
  public:
    void add_trajectory(std::span<const std::size_t> kept_indices) {
        m_kept.insert(m_kept.end(), kept_indices.begin(), kept_indices.end());
        m_offsets.push_back(m_kept.size());
    }

    std::size_t size() const { return m_offsets.size() - 1; }
    std::size_t num_points() const { return m_kept.size(); }

    std::span<const std::size_t> trajectory(std::size_t i) const {
        assert(i < size());
        return {m_kept.data() + m_offsets[i], m_offsets[i + 1] - m_offsets[i]};
    }

  private:
    std::vector<std::uint64_t> m_offsets{0};
    std::vector<std::size_t> m_kept;
};

// Builds a database holding only the kept points, with the same trajectories in the same order
TrajectoryDb materialize(const TrajectoryDb &trajectories, const Simplification &simplification);

} // namespace core

